import socket, struct, random
def q(name, server='127.0.0.11', qtype=1):
    tid = random.randint(0,65535)
    hdr = struct.pack('!HHHHHH', tid, 0x0100, 1, 0, 0, 0)
    qn = b''.join(bytes([len(l)]) + l.encode() for l in name.split('.')) + b'\x00'
    pkt = hdr + qn + struct.pack('!HH', qtype, 1)
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM); s.settimeout(2)
    s.sendto(pkt, (server,53))
    try:
        data,_ = s.recvfrom(4096)
        return data
    except Exception as e:
        return None
for name in ['prices.internal','commons.local']:
    for qt, n in [(1,'A'),(28,'AAAA'),(5,'CNAME'),(16,'TXT'),(33,'SRV'),(12,'PTR'),(2,'NS'),(6,'SOA')]:
        d = q(name, qtype=qt)
        if d:
            print(name, n, 'rcode=', d[3]&0xF, 'an=', struct.unpack('!H', d[6:8])[0], 'ns=', struct.unpack('!H', d[8:10])[0], d.hex()[:200])
        else:
            print(name, n, 'no response')
EOF"}

