import socket, concurrent.futures as cf
# UDP scan on forum host + re-verify full TCP range with longer timeout
def tcp(a):
    ip,p=a
    s=socket.socket(); s.settimeout(1.0)
    try:
        s.connect((ip,p)); return ('TCP',ip,p)
    except Exception: return None
    finally: s.close()
def udp(a):
    ip,p=a
    s=socket.socket(socket.AF_INET, socket.SOCK_DGRAM); s.settimeout(1.0)
    try:
        s.connect((ip,p)); s.sendto(b'\x00', (ip,p))
        try:
            s.recvfrom(1024); return ('UDP',ip,p)
        except socket.timeout: return None
    except Exception: return None
    finally: s.close()
targets=[('172.27.0.2',p) for p in range(1,1025)]
with cf.ThreadPoolExecutor(400) as ex:
    for r in ex.map(tcp, targets):
        if r: print(r)
print('tcp re-verify (1-1024, 1s timeout) done')
